function _gitaBnNum(n) {
  return String(n).replace(/[0-9]/g, function (d) {
    return '০১২৩৪৫৬৭৮৯'[Number(d)];
  });
}

function _gitaReadField(body, key) {
  // The source is a TypeScript data file whose verse values are ordinary
  // double-quoted strings. Parse only the fields we need; do not evaluate
  // the downloaded source as JavaScript.
  var match = body.match(
    new RegExp('(?:^|\\n)\\s*' + key + ':\\s*"((?:\\\\.|[^"\\\\])*)"', 'm')
  );
  return match ? JSON.parse('"' + match[1] + '"') : '';
}

function _gitaSourceToLyrics(source) {
  var chapters = [];
  var total = 0;

  for (var ch = 1; ch <= 18; ch++) {
    var start = source.indexOf(
      'const CH' + ch + ': Record<number, VerseContent> = {'
    );
    var end = start < 0 ? -1 : source.indexOf('\n};', start);
    if (start < 0 || end < 0) {
      throw new Error('Gita chapter ' + ch + ' is missing');
    }

    var block = source.slice(start, end + 3);
    var entries = [];
    var entryRe = /^\s*(\d+):\s*\{([\s\S]*?)^\s*\},?\s*$/gm;
    var entry;
    while ((entry = entryRe.exec(block))) {
      var verseNumber = Number(entry[1]);
      var body = entry[2];
      var sanskrit = _gitaReadField(body, 'sanskrit');
      var bengali = _gitaReadField(body, 'bengali');
      if (!sanskrit || !bengali) {
        throw new Error('Gita verse ' + ch + '.' + verseNumber + ' is incomplete');
      }
      entries.push({
        number: verseNumber,
        speaker: _gitaReadField(body, 'speaker'),
        sanskrit: sanskrit,
        bengali: bengali
      });
    }

    entries.sort(function (a, b) { return a.number - b.number; });
    if (entries.length !== GITA_CHAPTER_COUNTS[ch - 1]) {
      throw new Error(
        'Gita chapter ' + ch + ' has ' + entries.length + ' verses'
      );
    }
    total += entries.length;
    chapters.push(entries);
  }

  if (total !== 700) throw new Error('Gita contains ' + total + ' verses');

  var output = [];
  chapters.forEach(function (entries, chapterIndex) {
    var chapterNumber = chapterIndex + 1;
    output.push(
      '§§ অধ্যায়ঃ ' + _gitaBnNum(chapterNumber) + ' - ' +
      GITA_CHAPTER_NAMES[chapterIndex]
    );
    entries.forEach(function (verse) {
      output.push(
        '§ শ্লোক ' + _gitaBnNum(verse.number) + '\n' +
        (verse.speaker ? verse.speaker + '\n' : '') +
        verse.sanskrit + '\nঅর্থ: ' + verse.bengali
      );
    });
  });
  return output.join('\n');
}

function _gitaLooksComplete(text) {
  return typeof text === 'string' &&
    (text.match(/^§ শ্লোক /gm) || []).length === 700;
}

// Restore a successful previous load without blocking startup.
try {
  var _gitaCached = localStorage.getItem(GITA_CACHE_KEY);
  if (_gitaLooksComplete(_gitaCached)) {
    LYRICS[GITA_ID] = _gitaCached;
    _gitaReady = true;
  }
} catch (_) {}

function loadGitaLyrics() {
  if (_gitaReady) return Promise.resolve(LYRICS[GITA_ID]);
  if (_gitaLoadPromise) return _gitaLoadPromise;

  _gitaLoadPromise = fetch(GITA_DATA_URL)
    .then(function (response) {
      if (!response.ok) throw new Error('Gita data request failed');
      return response.text();
    })
    .then(function (source) {
      var lyrics = _gitaSourceToLyrics(source);
      LYRICS[GITA_ID] = lyrics;
      _gitaReady = true;
      try { localStorage.setItem(GITA_CACHE_KEY, lyrics); } catch (_) {}
      return lyrics;
    })
    .catch(function (error) {
      _gitaLoadPromise = null;
      throw error;
    });
  return _gitaLoadPromise;
}

window.loadGitaLyrics = loadGitaLyrics;
window.isGitaReady = function () { return _gitaReady; };

// ═══════════════════════════════════════════════════════
// SECTIONED-STOTRAM PICKER (svb, blv, …)
// All UI/logic for stotrams that have numbered sub-sections
// lives here so updates can be made in this file alone.
// Styling lives in style-stotram.css (.sts-* classes).
//
// Depends on these globals defined in app.js:
//   getEffectiveLyrics(id)  _renderVerse(idx,prev)  _initSwipeHandler()
//   _verses (array)         _verseIdx (number)
// ═══════════════════════════════════════════════════════
(function (global) {
  // Map of stotram-id → display title shown above the picker grid.
  var SECTIONED = {
    svb: 'শ্রী হিত সেবক বাণী',
    blv: 'বয়ালীস লীলা',
    gg:  'গীতগোবিন্দম্',
    bg:  'শ্রীমদ্ভগবদ্গীতা'
  };

  // Stotrams using two-level §§ / § hierarchy
  var TWO_LEVEL = { gg: true, bg: true };

  // Safely remove a #sts-picker (or similar) overlay. Plain el.remove() can
  // leave a visual "ghost" of the element on screen in iOS Safari, because
  // .sts-picker uses -webkit-overflow-scrolling:touch, which puts it on its
  // own GPU compositing layer — WebKit sometimes fails to repaint that
  // screen region when the layer is torn down mid-navigation, so the last
  // frame it painted (e.g. the geetam list) stays visible, overlapping
  // whatever renders next (e.g. the opened song's lyrics). Hiding the
  // element and forcing a reflow *before* removing it reliably avoids this.
  function _killPicker(el) {
    if (!el) return;
    el.style.display = 'none';
    void el.offsetHeight; // force a reflow/repaint before removal
    el.remove();
  }

  // Convert a Bengali-numeral string (e.g. "১২") to a JS number.
  var _bnDigits = '০১২৩৪৫৬৭৮৯';
  function _bnToNum(s) {
    var out = '';
    for (var i = 0; i < s.length; i++) {
      var di = _bnDigits.indexOf(s[i]);
      out += di === -1 ? s[i] : String(di);
    }
    return parseInt(out, 10);
  }

  var _sections = [];          // [{title, content}]
  var _activeId = null;        // current sectioned-stotram id
  var _inSectionView = false;
  function _isGitaMode() { return _activeId === 'bg'; }
  global.setGitaVerseTitle = function (idx) {
    if (_activeId !== 'bg') return;
    var title = document.getElementById('lmTitle');
    if (!title) return;
    title.textContent = 'শ্লোক ' + String(idx + 1).replace(/[0-9]/g, function (d) {
      return '০১২৩৪৫৬৭৮৯'[Number(d)];
    });
  };

  // ── Parse GG two-level: §§ = sarga, § = geetam ───────────────────────
  // Returns [{title, subs:[{title,content}], preamble}]
  function parseGG(ly) {
    var sargas = [];
    var curSarga = null;
    var curGeetam = null;
    var curLines = [];
    var preambleLines = [];
    var inPreamble = false;

    function flushGeetam() {
      if (curGeetam !== null && curSarga) {
        curSarga.subs.push({ title: curGeetam, content: curLines.join('\n').trim() });
      }
      curGeetam = null; curLines = [];
    }
    function flushSarga() {
      flushGeetam();
      if (curSarga) sargas.push(curSarga);
      curSarga = null;
    }

    var lines = ly.split('\n');
    for (var i = 0; i < lines.length; i++) {
      var line = lines[i].trim();
      if (line.startsWith('§§ ')) {
        flushSarga();
        var title = line.slice(3).trim();
        if (title === 'পূর্বভূমিকা') {
          inPreamble = true;
          curSarga = { title: title, subs: [], preamble: '' };
        } else {
          inPreamble = false;
          curSarga = { title: title, subs: [], preamble: '' };
        }
        continue;
      }
      if (line.startsWith('§ ')) {
        if (inPreamble && curSarga) {
          curSarga.preamble = preambleLines.join('\n').trim();
          preambleLines = [];
          inPreamble = false;
        }
        flushGeetam();
        curGeetam = line.slice(2).trim();
        continue;
      }
      if (inPreamble) {
        preambleLines.push(lines[i]);
      } else if (curGeetam !== null) {
        curLines.push(lines[i]);
      } else if (curSarga) {
        // Between §§ and first §: sarga preamble
        curSarga.preamble = (curSarga.preamble || '') + lines[i] + '\n';
      }
    }
    // Flush last preamble section
    if (inPreamble && curSarga) {
      curSarga.preamble = preambleLines.join('\n').trim();
    }
    flushSarga();
    return sargas;
  }

  var _ggSargas = [];   // parsed two-level structure for gg
  var _curSargaIdx = -1;

  // ── Show top-level Sarga picker for GG ───────────────────────────────
  function showSargaPicker(id) {
    _activeId = id;
    var ly = (typeof getEffectiveLyrics === 'function') ? getEffectiveLyrics(id) : '';
    _ggSargas = parseGG(ly || '');

    var lmo    = document.getElementById('lmo');
    var lmb    = document.getElementById('lmb');
    var lmNav  = document.getElementById('lmNav');
    var lmTitle= document.getElementById('lmTitle');
    var fsCtrl = document.getElementById('lyr-fs-ctrl');
    var oldWrap= document.getElementById('lm-translate-wrap');
    if (oldWrap) oldWrap.remove();
    if (lmb)    lmb.style.display    = 'none';
    if (lmNav)  lmNav.style.display  = 'none';
    if (lmTitle){ lmTitle.textContent = ''; lmTitle.style.display = 'none'; }
    if (fsCtrl) fsCtrl.style.display = 'none';
    ['sts-picker','sts-sub-picker'].forEach(function(pid){
      _killPicker(document.getElementById(pid));
    });

    var picker = document.createElement('div');
    picker.id = 'sts-picker';
    picker.className = 'sts-picker' + (window.innerWidth >= 600 ? ' sts-wide' : '');

    var titleDiv = document.createElement('div');
    titleDiv.className = 'sts-picker-title';
    titleDiv.textContent = SECTIONED[id] || '';
    picker.appendChild(titleDiv);

    var subtitle = document.createElement('div');
    subtitle.className = 'sts-picker-subtitle';
    subtitle.textContent = _isGitaMode() ? 'অধ্যায় নির্বাচন করুন' : 'সর্গ নির্বাচন করুন';
    picker.appendChild(subtitle);

    var glowColors = ['#ffd700','#ffaa00','#ff6bff','#00e5ff','#7dff6b',
      '#ff6b6b','#ffd700','#b388ff','#00ffcc','#ffaa00','#ffd700','#ff6bff','#00e5ff'];

    var grid = document.createElement('div');
    grid.className = 'sts-picker-grid';
    var rows = Math.max(1, Math.ceil(_ggSargas.length / 2));
    grid.style.gridTemplateRows = 'repeat(' + rows + ',auto)';

    _ggSargas.forEach(function(sarga, idx) {
      var btn = document.createElement('button');
      var gc = glowColors[idx % glowColors.length];
      btn.className = 'sts-btn';
      btn.style.setProperty('--gc', gc);
      btn.style.setProperty('--pd', (2.8 + (idx%5)*0.4).toFixed(1)+'s');
      btn.style.setProperty('--cd', (8 + (idx%4)*1.5).toFixed(1)+'s');
      btn.style.setProperty('--fd', (idx*0.045).toFixed(2)+'s');
      btn.style.setProperty('--od', '-'+(idx*0.6).toFixed(1)+'s');
      btn.style.setProperty('--ad', (idx*0.045).toFixed(2)+'s');

      var numSpan = document.createElement('span');
      numSpan.className = 'sts-btn-num';
      if (sarga.title === 'পূর্বভূমিকা') {
        numSpan.style.display = 'none';
      } else {
        var nm = sarga.title.match(/[০-৯]+/);
        numSpan.textContent = nm ? nm[0] : String(idx + 1);
      }

      var nameSpan = document.createElement('span');
      nameSpan.className = 'sts-btn-name';
      nameSpan.textContent = sarga.title === 'পূর্বভূমিকা' ? 'পূর্বভূমিকা' : sarga.title;
      // Geet Govindam: mark every sarga that has at least one song with music
      // (same rule as the 🎶 badge on the geetam list inside the sarga).
      if (id === 'gg' && sarga.title !== 'পূর্বভূমিকা' && typeof _AUDIO_STOTRAMS !== 'undefined' && _AUDIO_STOTRAMS.gg) {
        var _smN = sarga.title.match(/[০-৯]+/);
        var _smNum = _smN ? _bnToNum(_smN[0]) : (idx + 1);
        var _smPre = 'gg_' + _smNum + '_';
        var _smT = _AUDIO_STOTRAMS.gg.tracks || {}, _smY = _AUDIO_STOTRAMS.gg.ytTracks || {};
        var _smHas = Object.keys(_smT).concat(Object.keys(_smY)).some(function (k) { return k.indexOf(_smPre) === 0; });
        if (_smHas) nameSpan.textContent += ' 🎶';
      }

      btn.appendChild(numSpan);
      btn.appendChild(nameSpan);
      btn.onclick = (function(i){ return function(){ showGeetamPicker(i); }; })(idx);
      grid.appendChild(btn);
    });
    picker.appendChild(grid);

    var lmd = document.querySelector('.lmd');
    if (lmd) lmd.appendChild(picker);
    if (lmo) lmo.classList.add('show');
  }

  // ── Show Geetam sub-picker for one Sarga ─────────────────────────────
  function showGeetamPicker(sargaIdx) {
    _curSargaIdx = sargaIdx;
    var sarga = _ggSargas[sargaIdx];
    if (!sarga) return;

    var oldPicker = document.getElementById('sts-picker');
    _killPicker(oldPicker);
    if (sarga.title === 'পূর্বভূমিকা') {
      openGeetam(sargaIdx, -1);
      return;
    }

    var picker = document.createElement('div');
    picker.id = 'sts-picker';
    picker.className = 'sts-picker' + (window.innerWidth >= 600 ? ' sts-wide' : '');

    // Back button
    var backBtn = document.createElement('button');
    backBtn.className = 'sts-back-btn';
    backBtn.textContent = '←';
    backBtn.setAttribute('aria-label', _isGitaMode() ? 'অধ্যায় তালিকা' : 'সর্গ তালিকা');
    backBtn.onclick = function() { showSargaPicker(_activeId); };
    picker.appendChild(backBtn);

    var titleDiv = document.createElement('div');
    titleDiv.className = 'sts-picker-title';
    titleDiv.textContent = sarga.title;
    picker.appendChild(titleDiv);

    var subtitle = document.createElement('div');
    subtitle.className = 'sts-picker-subtitle';
    subtitle.textContent = _isGitaMode() ? 'শ্লোক নির্বাচন করুন' : 'গীতম্ নির্বাচন করুন';
    picker.appendChild(subtitle);

    var glowColors = ['#ffd700','#ffaa00','#ff6bff','#00e5ff','#7dff6b',
      '#ff6b6b','#ffd700','#b388ff','#00ffcc','#ffaa00'];

    // Preamble button (if sarga has preamble text)
    var items = [];
    sarga.subs.forEach(function(g, i){ items.push({ label: g.title, subIdx: i }); });

    // Sarga number (for building the same "gg_<sarga#>_<geetam#>" audio
    // key openGeetam uses) — lets the picker show a 🎶 badge on any
    // geetam that actually has a recorded clip in _AUDIO_STOTRAMS.gg.tracks.
    var _sNumMatch = sarga.title.match(/[০-৯]+/);
    var _sNum = _sNumMatch ? _bnToNum(_sNumMatch[0]) : (sargaIdx + 1);
    var _ggTracks = (typeof _AUDIO_STOTRAMS !== 'undefined' && _AUDIO_STOTRAMS.gg && _AUDIO_STOTRAMS.gg.tracks) || {};

    var _ggYt = (typeof _AUDIO_STOTRAMS !== 'undefined' && _AUDIO_STOTRAMS.gg && _AUDIO_STOTRAMS.gg.ytTracks) || {};
    var grid = document.createElement('div');
    grid.className = 'sts-picker-grid';
    var rows = Math.max(1, Math.ceil(items.length / 2));
    grid.style.gridTemplateRows = 'repeat(' + rows + ',auto)';

    items.forEach(function(item, idx) {
      var btn = document.createElement('button');
      var gc = glowColors[idx % glowColors.length];
      btn.className = 'sts-btn';
      btn.style.setProperty('--gc', gc);
      btn.style.setProperty('--pd', (2.8+(idx%5)*0.4).toFixed(1)+'s');
      btn.style.setProperty('--cd', (8+(idx%4)*1.5).toFixed(1)+'s');
      btn.style.setProperty('--fd', (idx*0.045).toFixed(2)+'s');
      btn.style.setProperty('--od', '-'+(idx*0.6).toFixed(1)+'s');
      btn.style.setProperty('--ad', (idx*0.045).toFixed(2)+'s');

      var numSpan = document.createElement('span');
      numSpan.className = 'sts-btn-num';
      numSpan.textContent = item.subIdx === -1 ? '॥' : String(idx + 1);

      var nameSpan = document.createElement('span');
      nameSpan.className = 'sts-btn-name';
      // Truncate long geetam titles
      var t = item.label;
      if (t.length > 40) t = t.slice(0, 38) + '…';
      var _gk = 'gg_' + _sNum + '_' + (item.subIdx + 1);
      var _hasAudio = item.subIdx !== -1 && (!!_ggTracks[_gk] || !!_ggYt[_gk]);
      nameSpan.textContent = t + (_hasAudio ? ' 🎶' : '');

      btn.appendChild(numSpan);
      btn.appendChild(nameSpan);
      btn.onclick = (function(si){ return function(){ openGeetam(sargaIdx, si); }; })(item.subIdx);
      grid.appendChild(btn);
    });
    picker.appendChild(grid);

    // Pre-load the hidden YouTube player(s) of this sarga's YouTube songs so
    // the song starts the instant it is opened.
    try {
      var _wl = [];
      Object.keys(_ggYt).forEach(function (k) {
        if (k.indexOf('gg_' + _sNum + '_') === 0) _wl.push({ key: 'gg:' + k, vid: _ggYt[k], start: 0 });
      });
      if (typeof _hcjWarmSet === 'function') _hcjWarmSet(_wl);
    } catch (_e) {}

    var lmd = document.querySelector('.lmd');
    if (lmd) lmd.appendChild(picker);
  }

  // ── Open one Geetam (or sarga preamble) in verse reader ──────────────
  function openGeetam(sargaIdx, subIdx) {
    var sarga = _ggSargas[sargaIdx];
    if (!sarga) return;

    var content, title;
    if (subIdx === -1) {
      // preamble of sarga (or whole preamble section)
      content = sarga.preamble || sarga.subs.map(function(s){return s.content;}).join('\n\n');
      title = sarga.title;
    } else {
      var geetam = sarga.subs[subIdx];
      if (!geetam) return;
      content = geetam.content;
      title = geetam.title;
    }

    // Audio key for gg (Geet Govindam): "gg_<sarga#>_<geetam#>" — read by
    // app.js's audio player (_AUDIO_STOTRAMS.gg.tracks). Every geetam here
    // renders as a single verse card (idx is always 0), so the player can't
    // tell songs apart by verse index the way other stotrams do — this key
    // is how it knows which song (if any) has a clip. Stop any audio that
    // was playing for the previous geetam before switching.
    if (_activeId === 'gg' && subIdx !== -1) {
      var _sNumMatch = sarga.title.match(/[০-৯]+/);
      var _sNum = _sNumMatch ? _bnToNum(_sNumMatch[0]) : (sargaIdx + 1);
      window._ggAudioKey = 'gg_' + _sNum + '_' + (subIdx + 1);
      window._bgChapterNum = null;
    } else if (_activeId === 'bg' && subIdx !== -1) {
      // Gita audio path is "bg_<chapter#>_<shlok#>.mp3" (see app.js's
      // _AUDIO_STOTRAMS.bg / _hcjAudioPath) — chapter number comes from
      // the sarga's own Bengali numeral, same extraction gg uses for its
      // sarga number.
      var _chNumMatch = sarga.title.match(/[০-৯]+/);
      window._bgChapterNum = _chNumMatch ? _bnToNum(_chNumMatch[0]) : (sargaIdx + 1);
      window._ggAudioKey = null;
    } else {
      window._ggAudioKey = null;
      window._bgChapterNum = null;
    }
    if (typeof _hcjStopAudio === 'function') _hcjStopAudio();

    _inSectionView = true;
    var picker = document.getElementById('sts-picker');
    _killPicker(picker);

    var lmb   = document.getElementById('lmb');
    var lmNav = document.getElementById('lmNav');
    if (lmb)   lmb.style.display = '';
    if (lmNav) lmNav.style.display = '';

    var fsCtrl = document.getElementById('lyr-fs-ctrl');
    if (fsCtrl) fsCtrl.style.display = '';

    var lmTitle = document.getElementById('lmTitle');
    if (lmTitle) {
      lmTitle.style.display = '';
      var shortTitle = title.length > 50 ? title.slice(0,48)+'…' : title;
      lmTitle.textContent = shortTitle;
    }

    if (typeof _verses !== 'undefined') {
      if (_activeId === 'bg' && subIdx !== -1) {
        // Gita chapters are a real verse sequence: keep the whole chapter
        // in the reader so the bottom previous/next arrows can move through
        // every shloka instead of rendering only the tapped one.
        _verses = sarga.subs.map(function (verse) {
          return verse.content.trim();
        });
        _verseIdx = subIdx;
        if (typeof _verseNavLocked !== 'undefined') _verseNavLocked = false;
      } else {
        // Geetam entries remain single-card readers.
        _verses = [content.trim()];
        _verseIdx = 0;
      }
      if (typeof _renderVerse === 'function') _renderVerse(_verseIdx, null);
      if (typeof _initSwipeHandler === 'function') _initSwipeHandler();
      // YouTube-backed geetam: use the pre-loaded player and start playing right away (same tap).
      if (_activeId === 'gg' && subIdx !== -1 && typeof _hcjAdoptWarm === 'function') {
        try { _hcjAdoptWarm(true); } catch (_e) {}
      }
    }

    // Back button in verse title bar
    var existingBack = document.getElementById('sts-verse-back');
    if (existingBack) existingBack.remove();
    var backBtn = document.createElement('button');
    backBtn.id = 'sts-verse-back';
    backBtn.className = 'sts-back-btn';
    backBtn.textContent = '←';
    backBtn.setAttribute('aria-label', _isGitaMode() ? 'শ্লোক তালিকা' : 'গীতম্ তালিকা');
    backBtn.onclick = function() {
      if (typeof _hcjStopAudio === 'function') _hcjStopAudio();
      window._ggAudioKey = null;
      window._bgChapterNum = null;
      backBtn.remove();
      // Leave the reader completely before rebuilding the sloka picker.
      // Keeping lmb/lmNav visible makes the new picker render over the old
      // verse card, which is especially noticeable on mobile browsers.
      var lmbBack = document.getElementById('lmb');
      var lmNavBack = document.getElementById('lmNav');
      var fsCtrlBack = document.getElementById('lyr-fs-ctrl');
      var translateBack = document.getElementById('lm-translate-wrap');
      var titleBack = document.getElementById('lmTitle');
      if (lmbBack) lmbBack.style.display = 'none';
      if (lmNavBack) lmNavBack.style.display = 'none';
      if (fsCtrlBack) fsCtrlBack.style.display = 'none';
      if (translateBack) translateBack.remove();
      if (titleBack) {
        titleBack.textContent = '';
        titleBack.style.display = 'none';
      }
      var lmoBack = document.getElementById('lmo');
      if (lmoBack) lmoBack.classList.remove('has-sts-back');
      showGeetamPicker(sargaIdx);
      _inSectionView = false;
    };
    if (lmTitle) lmTitle.parentNode.insertBefore(backBtn, lmTitle);
    var lmoFwd = document.getElementById('lmo');
    if (lmoFwd) lmoFwd.classList.add('has-sts-back');
  }

  // ── Parse lyrics into sections by Bengali-numeral headings ────────────
  function parseSections(ly) {
    var lines = ly.split('\n');
    var sections = [];
    var curTitle = null;
    var curLines = [];

    function isTitle(line) {
      if (/^[০-৯]+\./.test(line) && line.length < 100) return true;
      // SVB-only: phalashruti section (no numeral): শ্রী সেবক বাণী-ফল স্তুতি
      if (/ফল\s*(স্তুতি|শ্রুতি)/.test(line) && line.length < 100) return true;
      return false;
    }
    function flush() {
      if (curTitle && curLines.length > 0) {
        sections.push({ title: curTitle, content: curLines.join('\n').trim() });
      }
      curTitle = null; curLines = [];
    }

    for (var i = 0; i < lines.length; i++) {
      var raw = lines[i];
      var line = raw.trim();
      // Section closing marker: ! … !
      if (line.startsWith('!') && line.endsWith('!')) { flush(); continue; }
      if (isTitle(line)) {
        if (curTitle) flush();
        curTitle = line;
        continue;
      }
      if (curTitle) curLines.push(raw);
    }
    flush();
    return sections;
  }

  function isSectioned(id) { return Object.prototype.hasOwnProperty.call(SECTIONED, id); }
  function isTwoLevel(id)  { return Object.prototype.hasOwnProperty.call(TWO_LEVEL, id); }

  // ── Show the section picker grid ──────────────────────────────────────
  function showPicker(id) {
    if (isTwoLevel(id)) { showSargaPicker(id); return; }
    _activeId = id;
    var ly = (typeof getEffectiveLyrics === 'function') ? getEffectiveLyrics(id) : '';
    _sections = parseSections(ly || '');
    _inSectionView = false;

    var lmo = document.getElementById('lmo');
    var lmTitle = document.getElementById('lmTitle');
    if (lmTitle) { lmTitle.textContent = SECTIONED[id] || ''; lmTitle.style.display = 'none'; }

    // Hide verse-reader chrome
    var lmb   = document.getElementById('lmb');
    var lmNav = document.getElementById('lmNav');
    if (lmb)   lmb.style.display   = 'none';
    if (lmNav) lmNav.style.display = 'none';

    var oldWrap = document.getElementById('lm-translate-wrap');
    if (oldWrap) oldWrap.remove();

    var oldPicker = document.getElementById('sts-picker');
    _killPicker(oldPicker);

    var fsCtrl = document.getElementById('lyr-fs-ctrl');
    if (fsCtrl) fsCtrl.style.display = 'none';

    // Responsive numbers
    var vw = window.innerWidth;
    var isWide = vw >= 600;

    var picker = document.createElement('div');
    picker.id = 'sts-picker';
    picker.className = 'sts-picker' + (isWide ? ' sts-wide' : '');

    var titleDiv = document.createElement('div');
    titleDiv.id  = 'sts-picker-title';
    titleDiv.className = 'sts-picker-title';
    titleDiv.textContent = SECTIONED[id] || '';
    picker.appendChild(titleDiv);

    var subtitle = document.createElement('div');
    subtitle.className = 'sts-picker-subtitle';
    subtitle.textContent = 'বিভাগ নির্বাচন করুন';
    picker.appendChild(subtitle);

    // Grid (two columns, balanced rows)
    var grid = document.createElement('div');
    grid.className = 'sts-picker-grid';
    var rows = Math.max(1, Math.ceil(_sections.length / 2));
    grid.style.gridTemplateRows = 'repeat(' + rows + ',auto)';

    var glowColors = [
      '#ffd700','#ffaa00','#ff6bff','#00e5ff','#7dff6b',
      '#ff6b6b','#ffd700','#b388ff','#00ffcc','#ffaa00',
      '#ffd700','#ff6bff','#00e5ff','#7dff6b','#ff6b6b',
      '#ffd700','#b388ff'
    ];

    _sections.forEach(function (sec, idx) {
      var btn = document.createElement('button');
      var gc        = glowColors[idx % glowColors.length];
      var pulseDur  = (2.8 + (idx % 5) * 0.4).toFixed(1) + 's';
      var colorDur  = (8   + (idx % 4) * 1.5).toFixed(1) + 's';
      var fadeDelay = (idx * 0.045).toFixed(2) + 's';
      var colorOff  = '-' + (idx * 0.6).toFixed(1) + 's';

      btn.className = 'sts-btn';
      btn.style.setProperty('--gc', gc);
      btn.style.setProperty('--pd', pulseDur);
      btn.style.setProperty('--cd', colorDur);
      btn.style.setProperty('--fd', fadeDelay);
      btn.style.setProperty('--od', colorOff);
      btn.style.setProperty('--ad', fadeDelay);

      var numSpan = document.createElement('span');
      numSpan.className = 'sts-btn-num';
      numSpan.textContent = String(idx + 1);

      var nameSpan = document.createElement('span');
      nameSpan.className = 'sts-btn-name';
      nameSpan.textContent = sec.title.replace(/^[০-৯]+\.\s*/, '');

      btn.appendChild(numSpan);
      btn.appendChild(nameSpan);
      btn.onclick = function () { openSection(idx); };
      grid.appendChild(btn);
    });
    picker.appendChild(grid);

    var lmd = document.querySelector('.lmd');
    if (lmd) lmd.appendChild(picker);
    if (lmo) lmo.classList.add('show');
  }

  // ── Open one section in the verse reader ──────────────────────────────
  function openSection(idx) {
    var sec = _sections[idx];
    if (!sec) return;
    window._stSecIdx = idx; // used by app.js's daily pad tracker (Sevak Vani)

    _inSectionView = true;

    var picker = document.getElementById('sts-picker');
    _killPicker(picker);

    var lmb   = document.getElementById('lmb');
    var lmNav = document.getElementById('lmNav');
    if (lmb)   lmb.style.display   = '';
    if (lmNav) lmNav.style.display = '';

    var fsCtrl = document.getElementById('lyr-fs-ctrl');
    if (fsCtrl) fsCtrl.style.display = '';

    var lmTitle = document.getElementById('lmTitle');
    if (lmTitle) {
      lmTitle.style.display = '';
      lmTitle.textContent = sec.title.replace(/^[০-৯]+\.\s*/, '');
    }

    // Back-to-sections button
    var existing = document.getElementById('sts-back-btn');
    if (!existing) {
      var backBtn = document.createElement('button');
      backBtn.id  = 'sts-back-btn';
      backBtn.className = 'sts-back-btn';
      backBtn.textContent = '←';
      backBtn.setAttribute('aria-label', 'বিভাগ তালিকা');
      backBtn.onclick = function () {
        _inSectionView = false;
        var old = document.getElementById('sts-back-btn');
        if (old) old.remove();
        var lmb2   = document.getElementById('lmb');
        var lmNav2 = document.getElementById('lmNav');
        if (lmb2)   lmb2.style.display   = 'none';
        if (lmNav2) lmNav2.style.display = 'none';
        var w2 = document.getElementById('lm-translate-wrap');
        if (w2) w2.remove();
        showPicker(_activeId);
      };
      var lmo = document.getElementById('lmo');
      if (lmo) lmo.appendChild(backBtn);
    }

    // Split section content into verses, merge orphan অর্থ-only blocks back
    var allVerses = sec.content
      .split(/\n{2,}/)
      .map(function (b) { return b.trim(); })
      .filter(function (b) { return b.length > 0; });

    var merged = [];
    for (var i = 0; i < allVerses.length; i++) {
      var v = allVerses[i];
      var linesOnly = v.split('\n').filter(function (l) { return l.trim().length > 0; });
      var allArtha = linesOnly.length > 0 && linesOnly.every(function (l) {
        return /^(?:অর্থ|শব্দার্থ)\s*:/.test(l.trim());
      });
      if (allArtha && merged.length > 0) {
        merged[merged.length - 1] += '\n\n' + v;
      } else {
        merged.push(v);
      }
    }

    // FIX: app.js declares `_verses`/`_verseIdx` with `let` (script-scoped),
    // so assigning to window._verses does NOT update them. Route through
    // showLyrics() by temporarily un-sectioning this id and overriding the
    // lyrics getter to return only the chosen section's verses.
    var idToOpen        = _activeId;
    var savedTitle      = SECTIONED[idToOpen];
    var savedGetLyrics  = window.getEffectiveLyrics;
    var sectionLyrics   = merged.join('\n\n');

    delete SECTIONED[idToOpen];
    window.getEffectiveLyrics = function (qid) {
      if (qid === idToOpen) return sectionLyrics;
      return savedGetLyrics.apply(this, arguments);
    };
    try {
      if (typeof window.showLyrics === 'function') {
        window.showLyrics(idToOpen);
      }
    } finally {
      window.getEffectiveLyrics = savedGetLyrics;
      SECTIONED[idToOpen] = savedTitle;
    }

    // Re-apply section title (showLyrics overwrites lmTitle with stotram name)
    var lmTitle2 = document.getElementById('lmTitle');
    if (lmTitle2) lmTitle2.textContent = sec.title.replace(/^[০-৯]+\.\s*/, '');

    // Re-apply radha theme to the card (svb/blv aren't in shiv/radha lists
    // so showLyrics clears data-theme).
    var cardEl = document.querySelector('.lm-water-card');
    if (cardEl) cardEl.setAttribute('data-theme', 'radha');
    var lmoEl = document.getElementById('lmo');
    if (lmoEl) lmoEl.setAttribute('data-bg', 'radha');
  }

  // ── Reset, called by app.js when the lyrics modal is closed ───────────
  function reset() {
    _inSectionView = false;
    _sections = [];
    _activeId = null;
    _ggSargas = [];
    _curSargaIdx = -1;
    window._ggAudioKey = null;
    window._bgChapterNum = null;
    _killPicker(document.getElementById('sts-picker'));
    _killPicker(document.getElementById('sts-sub-picker'));
    var b  = document.getElementById('sts-verse-back');  if (b)  b.remove();
    var b2 = document.getElementById('sts-back-btn');    if (b2) b2.remove();
    var lmoReset = document.getElementById('lmo');
    if (lmoReset) lmoReset.classList.remove('has-sts-back');
  }

  global.StotramSections = {
    isSectioned:    isSectioned,
    isTwoLevel:     isTwoLevel,
    show:           showPicker,
    reset:          reset,
    parse:          parseSections,
    parseGG:        parseGG,
    inSectionView:  function () { return _inSectionView; },
    open:           function (i) { openSection(i); }   // PAD-TRACE v1
  };
})(window);
